         opacity: 0.3
     },

     //...

     DEFAULT: {
         colorize: [0.5, 0.5, 0.5]
     }
};

const model4 = xktLoader.load({
     id: "myModel4",
     src: "./models/xkt/Duplex.ifc.xkt",
