````javascript
import {Viewer, Mesh, buildTorusGeometry,
ReadableGeometry, PhongMaterial, Texture, AmbientLight} from "xeokit-sdk.es.js";

// Create a Viewer and arrange the camera

const viewer = new Viewer({
    canvasId: "myCanvas"
});

