                                            {
                                                projMatrix:       projMatrix,
                                                viewMatrix:       math.compareVec3(rtcOrigin, vec3zero) ? viewMatrix : createRTCViewMat(viewMatrix, rtcOrigin, tempMat4),
                                                viewNormalMatrix: viewParams.viewNormalMatrix,
                                                eye:              viewParams.eye
                                            });

                                        if (incrementDrawState) {
                                            frameCtx.drawElements++;
                                        }
                                    }
                                };
                            }
                        });
                };
                let renderer = isEager && instantiate();
                return {
                    drawLayer: (frameCtx, layer, renderPass) => {
                        if (! renderer) {
                            renderer = instantiate();
                        }
                        renderer.drawLayer(frameCtx, layer, renderPass);
                    },
                    revalidate: force => {
                        if (renderer && (force || (! renderer.getValid()))) {
                            renderer.destroy();
                            renderer = isEager && instantiate();
                        }
                    }
                };
            };

            // Pre-initialize certain renderers that would otherwise be lazy-initialised on user interaction,
            // such as picking or emphasis, so that there is no delay when user first begins interacting with the viewer.
            const eager = (createProgramSetup, subGeometry) => wrapRenderer(createProgramSetup, subGeometry, true);
            const lazy  = (createProgramSetup, subGeometry) => wrapRenderer(createProgramSetup, subGeometry, false);

            const makeColorProgram = (vars, geo, lights, sao) => ColorProgram(vars, geo, scene.logarithmicDepthBufferEnabled, lights, sao, primitive);

            const makePickDepthProgram   = (vars, geo, c) => c(PickDepthProgram(vars, geo, scene.logarithmicDepthBufferEnabled), true);
            const makePickMeshProgram    = (vars, geo, c) => c(PickMeshProgram(vars, geo, scene.logarithmicDepthBufferEnabled), true);
            const makePickNormalsProgram = (vars, geo, c, isFlat) => c(PickNormalsProgram(vars, geo, scene.logarithmicDepthBufferEnabled, isFlat), true);

            const makeSnapProgram = (vars, geo, c, isSnapInit, isPoints) => c(SnapProgram(vars, geo, isSnapInit, isPoints), true);

            if (primitive === "points") {
                cache[sceneId] = {
                    colorRenderers:     { "sao-": { "vertex": lazy((vars, geo, c) => c(makeColorProgram(vars, geo, null, null))) } },
                    occlusionRenderer:  lazy((vars, geo, c) => c(OcclusionProgram(vars, scene.logarithmicDepthBufferEnabled))),
                    pickDepthRenderer:  lazy(makePickDepthProgram),
                    pickMeshRenderer:   lazy(makePickMeshProgram),
                    // VBOBatchingPointsShadowRenderer has been implemented by 14e973df6268369b00baef60e468939e062ac320,
                    // but never used (and probably not maintained), as opposed to VBOInstancingPointsShadowRenderer in the same commit
                    // drawShadow has been nop in VBO point layers
                    // shadowRenderer:     instancing && lazy((vars, geo, c) => c(ShadowProgram(scene.logarithmicDepthBufferEnabled))),
                    silhouetteRenderer: lazy((vars, geo, c) => c(SilhouetteProgram(vars, geo, scene.logarithmicDepthBufferEnabled, true))),
                    snapInitRenderer:   lazy((vars, geo, c) => makeSnapProgram(vars, geo, c, true,  true)),
                    snapVertexRenderer: lazy((vars, geo, c) => makeSnapProgram(vars, geo, c, false, true), { vertices: true })
                };
            } else if (primitive === "lines") {
                cache[sceneId] = {
                    colorRenderers:     { "sao-": { "vertex": lazy((vars, geo, c) => c(makeColorProgram(vars, geo, null, null))) } },
                    silhouetteRenderer: lazy((vars, geo, c) => c(SilhouetteProgram(vars, geo, scene.logarithmicDepthBufferEnabled, true))),
                    snapInitRenderer:   lazy((vars, geo, c) => makeSnapProgram(vars, geo, c, true,  false)),
                    snapEdgeRenderer:   lazy((vars, geo, c) => makeSnapProgram(vars, geo, c, false, false), { vertices: false }),
                    snapVertexRenderer: lazy((vars, geo, c) => makeSnapProgram(vars, geo, c, false, false), { vertices: true })
                };
            } else {
                cache[sceneId] = {
                    colorRenderers: (function() {
                        // WARNING: Changing `useMaps' to `true' for DTX might have unexpected consequences while binding textures, as the DTX texture binding mechanism doesn't rely on `frameCtx.textureUnit` the way VBO does (see setSAORenderState);
                        const createLights = vars => createLightSetup(vars, scene._lightsState);
                        const createSAO = vars => {
                            const uSAOParams = vars.createUniform("vec4", "uSAOParams", (set, state) => set(state.legacyFrameCtx.saoParams));
                            const uOcclusionTexture = setupTexture(vars, "sampler2D", "uOcclusionTexture", LinearEncoding, (set, state) => set(state.legacyFrameCtx.occlusionTexture));
                            return {
                                getAmbient: (gl_FragCoord) => {
                                    // Doing SAO blend in the main solid fill draw shader just so that edge lines can be drawn over the top
                                    // Would be more efficient to defer this, then render lines later, using same depth buffer for Z-reject
                                    const uv          = `${gl_FragCoord}.xy / ${uSAOParams}.xy`; // / viewportWH
                                    const blendCutoff = `${uSAOParams}.z`;
                                    const blendFactor = `${uSAOParams}.w`;
                                    const unPackFactors = "(255. / 256.) / vec4(256. * 256. * 256., 256. * 256., 256., 1.)";
                                    return `(smoothstep(${blendCutoff}, 1.0, dot(${uOcclusionTexture(uv)}, ${unPackFactors})) * ${blendFactor})`;
                                }
                            };
                        };
                        const saoRenderers = function(useSao) {
                            const makeColorTextureProgram = (vars, geo, useAlphaCutoff) => ColorTextureProgram(vars, geo, scene, createLights(vars), useSao && createSAO(vars), useAlphaCutoff, scene.gammaOutput); // If gammaOutput set, then it expects that all textures and colors need to be outputted in premultiplied gamma. Default is false.
                            return {
                                "PBR": pbrSupported && lazy((vars, geo, c) => c(PBRProgram(vars, geo, scene, createLights(vars), useSao && createSAO(vars)))),
                                "texture": colorTextureSupported && {
                                    "alphaCutoff-": lazy((vars, geo, c) => c(makeColorTextureProgram(vars, geo, false))),
                                    "alphaCutoff+": lazy((vars, geo, c) => c(makeColorTextureProgram(vars, geo, true)))
                                },
                                "vertex": (surfaceHasNormals
                                           ? lazy((vars, geo, c) => c(makeColorProgram(vars, geo, createLights(vars), useSao && createSAO(vars))))
                                           : lazy((vars, geo, c) => c(FlatColorProgram(vars, geo, scene.logarithmicDepthBufferEnabled, createLights(vars), useSao && createSAO(vars)))))
                            };
                        };
                        return {
                            "sao-": saoRenderers(false),
                            "sao+": saoEnabled && saoRenderers(true)
                        };
                    })(),
                    depthRenderer:           lazy((vars, geo, c) => c(DepthProgram(vars, geo, scene.logarithmicDepthBufferEnabled))),
                    edgesRenderers: {
                        uniform: lazy((vars, geo, c) => c(EdgesProgram(vars, geo, scene.logarithmicDepthBufferEnabled, true)),  { vertices: false }),
                        vertex:  lazy((vars, geo, c) => c(EdgesProgram(vars, geo, scene.logarithmicDepthBufferEnabled, false)), { vertices: false })
                    },
                    occlusionRenderer:       lazy((vars, geo, c) => c(OcclusionProgram(vars, scene.logarithmicDepthBufferEnabled))),
                    pickDepthRenderer:       eager(makePickDepthProgram),
                    pickMeshRenderer:        eager(makePickMeshProgram),
                    pickNormalsFlatRenderer: eager((vars, geo, c) => makePickNormalsProgram(vars, geo, c, true)),
                    pickNormalsRenderer:     eager((vars, geo, c) => makePickNormalsProgram(vars, geo, c, false)),
                    shadowRenderer:          lazy((vars, geo, c) => c(ShadowProgram(vars, scene))),
                    silhouetteRenderer:      eager((vars, geo, c) => c(SilhouetteProgram(vars, geo, scene.logarithmicDepthBufferEnabled, false))),
                    snapInitRenderer:        eager((vars, geo, c) => makeSnapProgram(vars, geo, c, true,  false)),
                    snapEdgeRenderer:        eager((vars, geo, c) => makeSnapProgram(vars, geo, c, false, false), { vertices: false }),
                    snapVertexRenderer:      eager((vars, geo, c) => makeSnapProgram(vars, geo, c, false, false), { vertices: true })
                };
            }

            const revalidateAll = force => {
                (function rec(obj) {
                    if (obj.revalidate) {
                        obj.revalidate(force);
                    } else {
                        Object.values(obj).forEach(v => v && rec(v));
                    }
                })(cache[sceneId]);
            };
            const compile = () => revalidateAll(false);
            compile();
            scene.on("compile", compile);
            scene.on("destroyed", () => {
                delete cache[sceneId];
            });
        }
        return cache[sceneId];
    };
})();

export class Layer {

    constructor(model, primitive, origin) {

        this.model     = model;
        this.primitive = primitive;
        this.origin    = origin;

        this._meshes = [];
        // The axis-aligned World-space boundary of this Layer's positions.
        this._aabb = math.collapseAABB3();
        this._aabbDirty = true;
    }

    finalize() {
        if (! this._compiledPortions) {
            this._compiledPortions = this.compilePortions();
            this.solid = this._compiledPortions.solid;
            this.sortId = this._compiledPortions.sortId;
            this.layerTextureSet = this._compiledPortions.layerTextureSet;
            this.drawCalls = this._compiledPortions.drawCalls;
            this._renderers = this._compiledPortions.renderers;
            this._setFlags = this._compiledPortions.setFlags;

            this.setColor  = this._compiledPortions.setColor;
            this.setMatrix = this._compiledPortions.setMatrix;
            this.setOffset = this._compiledPortions.setOffset;

            this.getEachIndex = this._compiledPortions.getEachIndex;
            this.getEachVertex = this._compiledPortions.getEachVertex;
            this.readGeometryData = this._compiledPortions.readGeometryData;
            this.precisionRayPickSurface = this._compiledPortions.precisionRayPickSurface;

            // These counts are used to avoid unnecessary render passes
            this._countsByFlag = { };
            const setupFlagCount = (entityFlag, modelCountProperty) => {
                const cnt = {
                    count: 0,
                    fromFlags: (flags, onlyIncrement) => {
                        if (flags & entityFlag) {
                            cnt.count++;
                            this.model[modelCountProperty]++;
                        } else if (! onlyIncrement) {
                            cnt.count--;
                            this.model[modelCountProperty]--;
                        }
                    }
                };
                this._countsByFlag[entityFlag] = cnt;
            };
            setupFlagCount(ENTITY_FLAGS.VISIBLE,     "numVisibleLayerPortions");
            setupFlagCount(ENTITY_FLAGS.CULLED,      "numCulledLayerPortions");
            setupFlagCount(ENTITY_FLAGS.PICKABLE,    "numPickableLayerPortions");
            setupFlagCount(ENTITY_FLAGS.CLIPPABLE,   "numClippableLayerPortions");
            setupFlagCount(ENTITY_FLAGS.XRAYED,      "numXRayedLayerPortions");
            setupFlagCount(ENTITY_FLAGS.HIGHLIGHTED, "numHighlightedLayerPortions");
            setupFlagCount(ENTITY_FLAGS.SELECTED,    "numSelectedLayerPortions");
            if (this._renderers.edgesRenderers) {
                setupFlagCount(ENTITY_FLAGS.EDGES, "numEdgesLayerPortions");
            }

            // Optimize initFlags to not require Object.values call each time (adds up a lot)
            this._countsByFlagArr = Object.values(this._countsByFlag);
            this._numTransparentLayerPortions = 0;
        }
    }

    aabbChanged() { this._aabbDirty = true; }

    getAABB() {
        if (this._aabbDirty) { // Per-layer AABB for best RTC accuracy
            math.collapseAABB3(this._aabb);
            this._meshes.forEach(m => math.expandAABB3(this._aabb, m.aabb));
            this._aabbDirty = false;
        }
        return this._aabb;
    }

    __drawLayer(renderFlags, frameCtx, renderer, pass) {
        if ((this._countsByFlag[ENTITY_FLAGS.CULLED].count < this._portions.length) && (this._countsByFlag[ENTITY_FLAGS.VISIBLE].count > 0)) {
            const backfacePasses = (this.primitive !== "points") && (this.primitive !== "lines") && [
                RENDER_PASSES.COLOR_OPAQUE,
                RENDER_PASSES.COLOR_TRANSPARENT,
                RENDER_PASSES.PICK,
                RENDER_PASSES.SILHOUETTE_HIGHLIGHTED,
                RENDER_PASSES.SILHOUETTE_SELECTED,
                RENDER_PASSES.SILHOUETTE_XRAYED,
            ];
            if (backfacePasses && backfacePasses.includes(pass)) {
                // _updateBackfaceCull
                const backfaces = true; // See XCD-230
                if (frameCtx.backfaces !== backfaces) {
                    const gl = this.model.scene.canvas.gl;
                    if (backfaces) {
                        gl.disable(gl.CULL_FACE);
                    } else {
                        gl.enable(gl.CULL_FACE);
                    }
                    frameCtx.backfaces = backfaces;
                }
            }
            frameCtx.textureUnit = 0; // WIP Maybe only for (! snap)?
            renderer.drawLayer(frameCtx, this, pass);
        }
    }

    __setVec4FromMaterialColorAlpha(color, alpha, dst) {
        dst[0] = color[0];
        dst[1] = color[1];
        dst[2] = color[2];
        dst[3] = alpha;
        return dst;
    }

    // ---------------------- COLOR RENDERING -----------------------------------

    __drawColor(renderFlags, frameCtx, renderOpaque) {
        if ((renderOpaque ? (this._numTransparentLayerPortions < this._portions.length) : (this._numTransparentLayerPortions > 0))
            &&
            (this._countsByFlag[ENTITY_FLAGS.XRAYED].count < this._portions.length)) {
            const saoRenderer = (renderOpaque && frameCtx.withSAO && this._renderers.colorRenderers["sao+"]) || this._renderers.colorRenderers["sao-"];
            const renderer = ((frameCtx.pbrEnabled && saoRenderer["PBR"])
                              ? saoRenderer["PBR"]
                              : ((frameCtx.colorTextureEnabled && saoRenderer["texture"])
                                 ? saoRenderer["texture"][(this.layerTextureSet && (typeof(this.layerTextureSet.alphaCutoff) === "number")) ? "alphaCutoff+" : "alphaCutoff-"]
                                 : saoRenderer["vertex"]));
            const pass = renderOpaque ? RENDER_PASSES.COLOR_OPAQUE : RENDER_PASSES.COLOR_TRANSPARENT;
            this.__drawLayer(renderFlags, frameCtx, renderer, pass);
        }
    }

    drawColorOpaque(renderFlags, frameCtx) {
        this.__drawColor(renderFlags, frameCtx, true);
    }

    drawColorTransparent(renderFlags, frameCtx) {
        this.__drawColor(renderFlags, frameCtx, false);
    }

    // ---------------------- RENDERING SAO POST EFFECT TARGETS --------------

    drawDepth(renderFlags, frameCtx) {
        // Assume whatever post-effect uses depth (eg SAO) does not apply to transparent objects
        const renderer = this._renderers.depthRenderer;
        if (renderer && (this._numTransparentLayerPortions < this._portions.length) && (this._countsByFlag[ENTITY_FLAGS.XRAYED].count < this._portions.length)) {
            this.__drawLayer(renderFlags, frameCtx, renderer, RENDER_PASSES.COLOR_OPAQUE);
        }
    }

    // ---------------------- SILHOUETTE RENDERING -----------------------------------

    __drawSilhouette(renderFlags, frameCtx, material, renderPass) {
        frameCtx.programColor = this.__setVec4FromMaterialColorAlpha(material.fillColor, material.fillAlpha, tempVec4);
        this.__drawLayer(renderFlags, frameCtx, this._renderers.silhouetteRenderer, renderPass);
    }

    drawSilhouetteXRayed(renderFlags, frameCtx) {
        if (this._countsByFlag[ENTITY_FLAGS.XRAYED].count > 0) {
            this.__drawSilhouette(renderFlags, frameCtx, this.model.scene.xrayMaterial, RENDER_PASSES.SILHOUETTE_XRAYED);
        }
    }

    drawSilhouetteHighlighted(renderFlags, frameCtx) {
        if (this._countsByFlag[ENTITY_FLAGS.HIGHLIGHTED].count > 0) {
            this.__drawSilhouette(renderFlags, frameCtx, this.model.scene.highlightMaterial, RENDER_PASSES.SILHOUETTE_HIGHLIGHTED);
        }
    }

    drawSilhouetteSelected(renderFlags, frameCtx) {
        if (this._countsByFlag[ENTITY_FLAGS.SELECTED].count > 0) {
            this.__drawSilhouette(renderFlags, frameCtx, this.model.scene.selectedMaterial, RENDER_PASSES.SILHOUETTE_SELECTED);
        }
    }

    // ---------------------- EDGES RENDERING -----------------------------------

    __drawVertexEdges(renderFlags, frameCtx, renderPass) {
        const renderer = this._renderers.edgesRenderers && this._renderers.edgesRenderers.vertex;
        if (renderer && (this._countsByFlag[ENTITY_FLAGS.EDGES].count > 0)) {
            this.__drawLayer(renderFlags, frameCtx, renderer, renderPass);
        }
    }

    drawEdgesColorOpaque(renderFlags, frameCtx) {
        if (this._compiledPortions.edgesColorOpaqueAllowed()) {
            this.__drawVertexEdges(renderFlags, frameCtx, RENDER_PASSES.EDGES_COLOR_OPAQUE);
        }
    }

    drawEdgesColorTransparent(renderFlags, frameCtx) {
        if (this._numTransparentLayerPortions > 0) {
            this.__drawVertexEdges(renderFlags, frameCtx, RENDER_PASSES.EDGES_COLOR_TRANSPARENT);
        }
    }

    __drawUniformEdges(renderFlags, frameCtx, material, renderPass) {
        const renderer = this._renderers.edgesRenderers && this._renderers.edgesRenderers.uniform;
        if (renderer) {
            frameCtx.programColor = this.__setVec4FromMaterialColorAlpha(material.edgeColor, material.edgeAlpha, tempVec4);
            this.__drawLayer(renderFlags, frameCtx, renderer, renderPass);
        }
    }

    drawEdgesHighlighted(renderFlags, frameCtx) {
        if (this._countsByFlag[ENTITY_FLAGS.HIGHLIGHTED].count > 0) {
            this.__drawUniformEdges(renderFlags, frameCtx, this.model.scene.highlightMaterial, RENDER_PASSES.EDGES_HIGHLIGHTED);
        }
    }

    drawEdgesSelected(renderFlags, frameCtx) {
        if (this._countsByFlag[ENTITY_FLAGS.SELECTED].count > 0) {
            this.__drawUniformEdges(renderFlags, frameCtx, this.model.scene.selectedMaterial, RENDER_PASSES.EDGES_SELECTED);
        }
    }

    drawEdgesXRayed(renderFlags, frameCtx) {
        if (this._countsByFlag[ENTITY_FLAGS.XRAYED].count > 0) {
            this.__drawUniformEdges(renderFlags, frameCtx, this.model.scene.xrayMaterial, RENDER_PASSES.EDGES_XRAYED);
        }
    }

    //---- PICKING ----------------------------------------------------------------------------------------------------

    __drawPick(renderFlags, frameCtx, renderer) {
        if (renderer) {
            this.__drawLayer(renderFlags, frameCtx, renderer, RENDER_PASSES.PICK);
        }
    }

    drawPickMesh(renderFlags, frameCtx) {
        this.__drawPick(renderFlags, frameCtx, this._renderers.pickMeshRenderer);
    }

    drawPickDepths(renderFlags, frameCtx) {
        this.__drawPick(renderFlags, frameCtx, this._renderers.pickDepthRenderer);
    }

    drawPickNormals(renderFlags, frameCtx) {
        const renderer = (false // TODO for VBO: this._state.normalsBuf
                          ? this._renderers.pickNormalsRenderer
                          : this._renderers.pickNormalsFlatRenderer);
        this.__drawPick(renderFlags, frameCtx, renderer);
    }

    drawSnap(renderFlags, frameCtx, isSnapInit) {
        frameCtx.snapPickOrigin = [0, 0, 0];

        const aabb = this.getAABB();
        frameCtx.snapPickCoordinateScale = math.mulVec3Scalar(
            safeInvVec3([ aabb[3] - aabb[0], aabb[4] - aabb[1], aabb[5] - aabb[2] ]),
            math.MAX_INT);

        const renderer = isSnapInit ? this._renderers.snapInitRenderer : ((frameCtx.snapMode === "edge") ? this._renderers.snapEdgeRenderer : this._renderers.snapVertexRenderer);
        this.__drawPick(renderFlags, frameCtx, renderer);

        frameCtx.snapPickLayerParams.push({
            origin: frameCtx.snapPickOrigin.slice(),
            coordinateScale: safeInvVec3(frameCtx.snapPickCoordinateScale)
        });
    }


    drawOcclusion(renderFlags, frameCtx) {
        const renderer = this._renderers.occlusionRenderer;
        if (renderer) {
            this.__drawLayer(renderFlags, frameCtx, renderer, RENDER_PASSES.COLOR_OPAQUE);
        }
    }

    drawShadow(renderFlags, frameCtx) {
        const renderer = this._renderers.shadowRenderer;
        if (renderer) {
            this.__drawLayer(renderFlags, frameCtx, renderer, RENDER_PASSES.COLOR_OPAQUE);
        }
    }


    initFlags(portionId, flags, transparent) {
        this._countsByFlagArr.forEach(cnt => cnt.fromFlags(flags, true));

        if (transparent) {
            this._numTransparentLayerPortions++;
            this.model.numTransparentLayerPortions++;
        }
        const deferred = (this.primitive !== "points");
        this._setFlags(portionId, flags, transparent, deferred);
        this._compiledPortions.setFlags2(portionId, flags, deferred);
    }

    flushInitFlags() {
        this._compiledPortions.setDeferredFlags();
    }

    setVisible(portionId, flags, transparent) {
        this._countsByFlag[ENTITY_FLAGS.VISIBLE].fromFlags(flags);
        this._setFlags(portionId, flags, transparent);
    }

    setCulled(portionId, flags, transparent) {
        this._countsByFlag[ENTITY_FLAGS.CULLED].fromFlags(flags);
        this._setFlags(portionId, flags, transparent);
    }

    setPickable(portionId, flags, transparent) {
        this._countsByFlag[ENTITY_FLAGS.PICKABLE].fromFlags(flags);
        this._setFlags(portionId, flags, transparent);
    }

    setClippable(portionId, flags) {
        this._countsByFlag[ENTITY_FLAGS.CLIPPABLE].fromFlags(flags);
        this._compiledPortions.setClippableFlags(portionId, flags);
    }

    setCollidable(portionId, flags) {
    }

    setXRayed(portionId, flags, transparent) {
        this._countsByFlag[ENTITY_FLAGS.XRAYED].fromFlags(flags);
        this._setFlags(portionId, flags, transparent);
    }

    setHighlighted(portionId, flags, transparent) {
        this._countsByFlag[ENTITY_FLAGS.HIGHLIGHTED].fromFlags(flags);
        this._setFlags(portionId, flags, transparent);
    }

    setSelected(portionId, flags, transparent) {
        this._countsByFlag[ENTITY_FLAGS.SELECTED].fromFlags(flags);
        this._setFlags(portionId, flags, transparent);
    }

    setEdges(portionId, flags, transparent) {
        if (this._countsByFlag[ENTITY_FLAGS.EDGES]) {
            this._countsByFlag[ENTITY_FLAGS.EDGES].fromFlags(flags);
            this._setFlags(portionId, flags, transparent);
        }
    }

    setTransparent(portionId, flags, transparent) {
        if (transparent) {
            this._numTransparentLayerPortions++;
            this.model.numTransparentLayerPortions++;
        } else {
            this._numTransparentLayerPortions--;
            this.model.numTransparentLayerPortions--;
        }
        this._setFlags(portionId, flags, transparent);
    }

    destroy() {
        this._compiledPortions && this._compiledPortions.destroy();
    }
}

export const ColorProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled, lightSetup, sao, primitive) {
    const vColor = programVariables.createVarying("vec4", "vColor", () => {
        const attributes = geometry.attributes;
        const color = (primitive === "points") ? `vec4(${attributes.color}.rgb, 1.0)` : `${attributes.color}`;
        if (lightSetup) {
            const lightComponents = [
                lightSetup.getAmbientColor()
            ].concat(
                lightSetup.directionalLights.map(
                    light => `max(dot(${attributes.normal.view}, ${light.getDirection(geometry.viewMatrix, attributes.position.view)}), 0.0) * ${light.getColor()}`));
            return `vec4(${lightComponents.join(" + ")}, 1) * ${color}`;
        } else {
            return color;
        }
    });
    const outColor = programVariables.createOutput("vec4", "outColor");
    return {
        programName: "Color",
        getHash: () => [lightSetup ? lightSetup.getHash() : "-", sao ? "sao" : "nosao"],
        cleanerEdges: true,
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => ((primitive !== "points") && (primitive !== "lines")) ? `${vFragDepth} + length(vec2(dFdx(${vFragDepth}), dFdy(${vFragDepth})))` : vFragDepth),
        renderPassFlag: 0,  // COLOR_OPAQUE | COLOR_TRANSPARENT
        appendFragmentOutputs: (src, getGammaOutputExpression, gl_FragCoord, sliceColorOr) => {
            if ((primitive === "points") || (primitive === "lines")) {
                src.push(`${outColor} = ${vColor};`);
            } else {
                src.push(`vec4 fragColor = ${sliceColorOr(vColor)};`);
                src.push(`${outColor} = ${(sao ? (`vec4(fragColor.rgb * ${sao.getAmbient(gl_FragCoord)}, fragColor.a)`) : "fragColor")};`);
            }
        },

        filterIntensityRange: true,
        incrementDrawState: true
    };
};

import {LinearEncoding, sRGBEncoding} from "../../../constants/constants.js";
import {setupTexture} from "../../../webgl/WebGLRenderer.js";

export const ColorTextureProgram = function(programVariables, geometry, scene, lightSetup, sao, useAlphaCutoff, gammaOutput) {
    const colorTexture = setupTexture(programVariables, "sampler2D", "uColorMap", sRGBEncoding, (set, state) => {
        const texture = state.layerTextureSet.colorTexture;
        texture && set(texture.texture);
    });
    const materialAlphaCutoff = useAlphaCutoff && programVariables.createUniform("float", "materialAlphaCutoff", (set, state) => set(state.layerTextureSet.alphaCutoff));

    const attributes = geometry.attributes;
    const vViewPosition = programVariables.createVarying("vec3", "vViewPosition", () => `${attributes.position.view}.xyz`);
    const vUV           = programVariables.createVarying("vec2", "vUV",           () => attributes.uv);
    const vColor        = programVariables.createVarying("vec4", "vColor",        () => attributes.color);

    const outColor = programVariables.createOutput("vec4", "outColor");

    return {
        programName: "ColorTexture",
        getHash: () => [lightSetup.getHash(), sao ? "sao" : "nosao", !!gammaOutput, useAlphaCutoff ? "alphaCutoffYes" : "alphaCutoffNo"],
        getLogDepth: scene.logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 0,      // COLOR_OPAQUE | COLOR_TRANSPARENT
        appendFragmentOutputs: (src, getGammaOutputExpression, gl_FragCoord, sliceColorOr) => {
            src.push(`vec3 viewNormal = normalize(cross(dFdx(${vViewPosition}), dFdy(${vViewPosition})));`);
            src.push("vec3 reflectedColor = vec3(0.0, 0.0, 0.0);");
            lightSetup.directionalLights.forEach(light => {
                src.push(`reflectedColor += max(dot(viewNormal, ${light.getDirection(geometry.viewMatrix, vViewPosition)}), 0.0) * ${light.getColor()};`);
            });

            src.push(`vec4 color = vec4(${lightSetup.getAmbientColor()} + reflectedColor, 1) * ${sliceColorOr(vColor)};`);

            src.push(`vec4 sampleColor = ${colorTexture(vUV)};`);

            if (materialAlphaCutoff) {
                src.push(`if (sampleColor.a < ${materialAlphaCutoff}) { discard; }`);
            }

            src.push("vec4 colorTexel = color * sampleColor;");
            src.push(`${outColor} = vec4(colorTexel.rgb${(sao ? (" * " + sao.getAmbient(gl_FragCoord)) : "")}, color.a);`);

            getGammaOutputExpression && src.push(`${outColor} = ${getGammaOutputExpression(outColor)};`);
        },

        incrementDrawState: true
    };
};

export const DepthProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled) {
    const vHighPrecisionZW = programVariables.createVarying("highp vec2", "vHighPrecisionZW", () => `${geometry.attributes.position.clip}.zw`);
    const outColor = programVariables.createOutput("vec4", "outColor");
    return {
        programName: "Depth",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 0,  // COLOR_OPAQUE | COLOR_TRANSPARENT
        // isn't it the same as vec4(vec3(1.0 - gl_FragCoord.z), 1.0) ?
        appendFragmentOutputs: (src) => src.push(`${outColor} = vec4(vec3((1.0 - ${vHighPrecisionZW}[0] / ${vHighPrecisionZW}[1]) / 2.0), 1.0);`)
    };
};

export const EdgesProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled, colorUniform) {
    const edgeColorUniform = colorUniform && programVariables.createUniform("vec4", "edgeColor", (set, state) => set(state.legacyFrameCtx.programColor));
    const color = geometry.attributes.color;
    const vColor = (!colorUniform) && programVariables.createVarying("vec4", "vColor", () => `vec4(${color}.rgb * 0.5, ${color}.a)`);
    const outColor = programVariables.createOutput("vec4", "outColor");
    return {
        programName: colorUniform ? "Edges" : "EdgesColor",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 2,  // EDGES_COLOR_OPAQUE | EDGES_COLOR_TRANSPARENT | EDGES_HIGHLIGHTED | EDGES_XRAYED | EDGES_SELECTED
        appendFragmentOutputs: (src) => src.push(`${outColor} = ${edgeColorUniform || vColor};`)
    };
};

export const FlatColorProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled, lightSetup, sao) {
    const attributes = geometry.attributes;
    const vViewPosition = programVariables.createVarying("vec3", "vViewPosition", () => `${attributes.position.view}.xyz`);
    const vColor = programVariables.createVarying("vec4", "vColor", () => attributes.color);
    const outColor = programVariables.createOutput("vec4", "outColor");
    return {
        programName: "FlatColor",
        getHash: () => [lightSetup.getHash(), sao ? "sao" : "nosao"],
        cleanerEdges: true,
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 0,      // COLOR_OPAQUE | COLOR_TRANSPARENT
        appendFragmentOutputs: (src, getGammaOutputExpression, gl_FragCoord, sliceColorOr) => {
            src.push(`vec3 viewNormal = normalize(cross(dFdx(${vViewPosition}), dFdy(${vViewPosition})));`);
            const lightComponents = [
                lightSetup.getAmbientColor()
            ].concat(
                lightSetup.directionalLights.map(
                    light => `max(dot(viewNormal, ${light.getDirection(geometry.viewMatrix, vViewPosition)}), 0.0) * ${light.getColor()}`));

            src.push(`vec4 fragColor = vec4(${lightComponents.join(" + ")}, 1) * ${sliceColorOr(vColor)};`);
            src.push(`${outColor} = ${sao ? `vec4(fragColor.rgb * ${sao.getAmbient(gl_FragCoord)}, fragColor.a)` : "fragColor"};`);
        }
    };
};

export const OcclusionProgram = function(programVariables, logarithmicDepthBufferEnabled) {
    const outColor = programVariables.createOutput("vec4", "outColor");
    return {
        programName: "Occlusion",
        // Logarithmic depth buffer involves an accuracy tradeoff, sacrificing
        // accuracy at close range to improve accuracy at long range. This can
        // mess up accuracy for occlusion tests, so we'll disable for now.
        getLogDepth: false && logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 0,  // COLOR_OPAQUE // Only opaque objects can be occluders
        appendFragmentOutputs: (src) => src.push(`${outColor} = vec4(0.0, 0.0, 1.0, 1.0);`) // Occluders are blue
    };
};

import {LinearEncoding, sRGBEncoding} from "../../../constants/constants.js";
import {setupTexture} from "../../../webgl/WebGLRenderer.js";

export const PBRProgram = function(programVariables, geometry, scene, lightSetup, sao) {
    const setup2dTexture = (name, isSrgb, getTexture) => {
        return setupTexture(programVariables, "sampler2D", name, isSrgb ? sRGBEncoding : LinearEncoding, (set, state) => {
            const texture = getTexture(state.layerTextureSet);
            texture && set(texture.texture);
        });
    };

    const attributes = geometry.attributes;
    const getIrradiance = lightSetup.getIrradiance;

    const colorMap         = setup2dTexture("uColorMap",         true,  textureSet => textureSet.colorTexture);
    const metallicRoughMap = setup2dTexture("uMetallicRoughMap", false, textureSet => textureSet.metallicRoughnessTexture);
    const emissiveMap      = setup2dTexture("uEmissiveMap",      true,  textureSet => textureSet.emissiveTexture);
    const normalMap        = setup2dTexture("uNormalMap",        false, textureSet => textureSet.normalsTexture);
    const aOMap            = setup2dTexture("uAOMap",            false, textureSet => textureSet.occlusionTexture);

    const vViewPosition      = programVariables.createVarying("vec3", "vViewPosition",      () => `${attributes.position.view}.xyz`);
    const vViewNormal        = programVariables.createVarying("vec3", "vViewNormal",        () => attributes.normal.view);
    const vColor             = programVariables.createVarying("vec4", "vColor",             () => attributes.color);
    const vUV                = programVariables.createVarying("vec2", "vUV",                () => attributes.uv);
    const vMetallicRoughness = programVariables.createVarying("vec2", "vMetallicRoughness", () => attributes.metallicRoughness);
    const vWorldNormal       = programVariables.createVarying("vec3", "vWorldNormal",       () => `${attributes.normal.world}.xyz`);

    const outColor = programVariables.createOutput("vec4", "outColor");

    const saturate = programVariables.createFragmentDefinition(
        "saturate",
        (name, src) => src.push(`float ${name}(const in float a) { return clamp(a, 0.0, 1.0); }`));

    const BRDF_Specular_GGX = programVariables.createFragmentDefinition(
        "BRDF_Specular_GGX",
        (name, src) => {
            src.push("vec3 F_Schlick(const in vec3 specularColor, const in float dotLH) {");
            src.push("   float fresnel = exp2( ( -5.55473 * dotLH - 6.98316 ) * dotLH );");
            src.push("   return ( 1.0 - specularColor ) * fresnel + specularColor;");
            src.push("}");

            src.push("float G_GGX_Smith(const in float alpha, const in float dotNL, const in float dotNV) {");
            src.push("   float a2 = ( alpha * alpha );");
            src.push("   float gl = dotNL + sqrt( a2 + ( 1.0 - a2 ) * ( dotNL * dotNL ) );");
            src.push("   float gv = dotNV + sqrt( a2 + ( 1.0 - a2 ) * ( dotNV * dotNV ) );");
            src.push("   return 1.0 / ( gl * gv );");
            src.push("}");

            src.push("float G_GGX_SmithCorrelated(const in float alpha, const in float dotNL, const in float dotNV) {");
            src.push("   float a2 = ( alpha * alpha );");
            src.push("   float gv = dotNL * sqrt( a2 + ( 1.0 - a2 ) * ( dotNV * dotNV ) );");
            src.push("   float gl = dotNV * sqrt( a2 + ( 1.0 - a2 ) * ( dotNL * dotNL ) );");
            src.push("   return 0.5 / max( gv + gl, 1e-6 );");
            src.push("}");

            src.push("float D_GGX(const in float alpha, const in float dotNH) {");
            src.push("   float a2 = ( alpha * alpha );");
            src.push("   float denom = ( dotNH * dotNH) * ( a2 - 1.0 ) + 1.0;");
            src.push("   return 0.31830988618 * a2 / ( denom * denom);"); // 1/PI
            src.push("}");

            src.push(`vec3 ${name}(const in vec3 incidentLightDirection, const in vec3 viewNormal, const in vec3 viewEyeDir, const in vec3 specularColor, const in float roughness) {`);
            src.push("   float alpha = ( roughness * roughness );");
            src.push("   vec3 halfDir = normalize( incidentLightDirection + viewEyeDir );");
            src.push(`   float dotNL = ${saturate}( dot( viewNormal, incidentLightDirection ) );`);
            src.push(`   float dotNV = ${saturate}( dot( viewNormal, viewEyeDir ) );`);
            src.push(`   float dotNH = ${saturate}( dot( viewNormal, halfDir ) );`);
            src.push(`   float dotLH = ${saturate}( dot( incidentLightDirection, halfDir ) );`);
            src.push("   vec3  F = F_Schlick( specularColor, dotLH );");
            src.push("   float G = G_GGX_SmithCorrelated( alpha, dotNL, dotNV );");
            src.push("   float D = D_GGX( alpha, dotNH );");
            src.push("   return F * (G * D);");
            src.push("}");
        });

    const BRDF_Specular_GGX_Environment = programVariables.createFragmentDefinition(
        "BRDF_Specular_GGX_Environment",
        (name, src) => {
            src.push(`vec3 ${name}(const in vec3 viewNormal, const in vec3 viewEyeDir, const in vec3 specularColor, const in float roughness) {`);
            src.push(`   float dotNV = ${saturate}(dot(viewNormal, viewEyeDir));`);
            src.push("   const vec4 c0 = vec4( -1, -0.0275, -0.572,  0.022);");
            src.push("   const vec4 c1 = vec4(  1,  0.0425,   1.04, -0.04);");
            src.push("   vec4 r = roughness * c0 + c1;");
            src.push("   float a004 = min(r.x * r.x, exp2(-9.28 * dotNV)) * r.x + r.y;");
            src.push("   vec2 AB    = vec2(-1.04, 1.04) * a004 + r.zw;");
            src.push("   return specularColor * AB.x + AB.y;");
            src.push("}");
        });

    const perturbNormal2Arb = programVariables.createFragmentDefinition(
        "perturbNormal2Arb",
        (name, src) => {
            src.push(`vec3 ${name}( vec3 eye_pos, vec3 surf_norm, vec2 uv, vec4 texel ) {`);
            src.push("      if (texel.r == 0.0 && texel.g == 0.0 && texel.b == 0.0) {");
            src.push("             return surf_norm;");
            src.push("      }");
            src.push("      vec3 q0 = vec3( dFdx( eye_pos.x ), dFdx( eye_pos.y ), dFdx( eye_pos.z ) );");
            src.push("      vec3 q1 = vec3( dFdy( eye_pos.x ), dFdy( eye_pos.y ), dFdy( eye_pos.z ) );");
            src.push("      vec2 st0 = dFdx( uv.st );");
            src.push("      vec2 st1 = dFdy( uv.st );");
            src.push("      vec3 S = normalize( q0 * st1.t - q1 * st0.t );");
            src.push("      vec3 T = normalize( -q0 * st1.s + q1 * st0.s );");
            src.push("      vec3 N = normalize( surf_norm );");
            src.push("      vec3 mapN = texel.xyz * 2.0 - 1.0;");
            src.push("      mat3 tsn = mat3( S, T, N );");
            //     src.push("      mapN *= 3.0;");
            src.push("      return normalize( tsn * mapN );");
            src.push("}");
        });

    return {
        programName: "PBR",
        getHash: () => [lightSetup.getHash(), sao ? "sao" : "nosao", !!scene.gammaOutput],
        getLogDepth: scene.logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 0,      // COLOR_OPAQUE | COLOR_TRANSPARENT
        clippingCaps: scene._sectionPlanesState.clippingCaps && outColor,
        incrementDrawState: true,
        appendFragmentOutputs: (src, getGammaOutputExpression, gl_FragCoord) => {
            src.push("const float PI = 3.14159265359;");
            src.push("vec3 reflDiff = vec3(0.0);");
            src.push("vec3 reflSpec = vec3(0.0);");

            src.push(`vec3 rgb = ${vColor}.rgb;`);
            src.push(`float opacity = ${vColor}.a;`);

            src.push("vec3  baseColor  = rgb;");
            src.push("float specularF0 = 1.0;");
            src.push(`float metallic   = float(${vMetallicRoughness}.r) / 255.0;`);
            src.push(`float roughness  = float(${vMetallicRoughness}.g) / 255.0;`);
            src.push("float dielectricSpecular = 0.16 * specularF0 * specularF0;");

            src.push(`vec4 colorTexel = ${colorMap(vUV)};`);
            src.push("baseColor *= colorTexel.rgb;");
            // src.push("opacity *=/= colorTexel.a;"); // batching had "*=", instancing had "="

            src.push(`vec3 metalRoughTexel = ${metallicRoughMap(vUV)}.rgb;`);
            src.push("metallic *= metalRoughTexel.b;");
            src.push("roughness *= metalRoughTexel.g;");

            src.push("vec3 diffuseColor       = baseColor * (1.0 - dielectricSpecular) * (1.0 - metallic);");
            src.push("float specularRoughness = clamp(roughness, 0.04, 1.0);");
            src.push("vec3 specularColor      = mix(vec3(dielectricSpecular), baseColor, metallic);");

            src.push(`vec3 viewNormal = -${perturbNormal2Arb}(${vViewPosition}, normalize(${vViewNormal}), ${vUV}, ${normalMap(vUV)});`);
            src.push(`vec3 viewEyeDir = normalize(${vViewPosition});`);

            getIrradiance && src.push(`reflDiff += ${getIrradiance(`normalize(${vWorldNormal})`)};`);

            if (lightSetup.getReflection) {
                const reflectVec = `reflect(viewEyeDir, viewNormal)`;
                const viewReflectVec = `normalize((vec4(${reflectVec}, 0.0) * ${geometry.viewMatrix}).xyz)`;
                const maxMIPLevel = "8.0";
                const blinnExpFromRoughness = `(2.0 / pow(specularRoughness + 0.0001, 2.0) - 2.0)`;
                const desiredMIPLevel = `${maxMIPLevel} - 0.79248 - 0.5 * log2(pow(${blinnExpFromRoughness}, 2.0) + 1.0)`;
                const specularMIPLevel = `0.5 * clamp(${desiredMIPLevel}, 0.0, ${maxMIPLevel})`; // TODO: a random factor - fix this
                const radiance = lightSetup.getReflection(viewReflectVec, specularMIPLevel);
                const specularBRDFContrib = `${BRDF_Specular_GGX_Environment}(viewNormal, viewEyeDir, specularColor, specularRoughness)`;
                src.push(`reflSpec += ${radiance} * ${specularBRDFContrib};`);
            }

            lightSetup.directionalLights.forEach((light, i) => {
                src.push(`vec3 lightDirection${i} = -${light.getDirection(geometry.viewMatrix, vViewPosition)};`); // This "-" might be wrong, but it used to be like that
                const dotNL = `${saturate}(dot(viewNormal, lightDirection${i}))`;
                src.push(`vec3 irradiance${i} = ${dotNL} * ${light.getColor()};`);
                src.push(`reflDiff += irradiance${i};`);
                src.push(`reflSpec += irradiance${i} * PI * ${BRDF_Specular_GGX}(lightDirection${i}, viewNormal, viewEyeDir, specularColor, specularRoughness);`);
            });

            src.push(`vec3 emissiveColor = ${emissiveMap(vUV)}.rgb;`); // TODO: correct gamma function
            src.push(`float aoFactor = ${aOMap(vUV)}.r;`);

            const ambient = `${lightSetup.getAmbientColor()} * baseColor * opacity * rgb`;
            src.push(`vec3 outgoingLight = emissiveColor + reflDiff * diffuseColor + reflSpec + ${ambient};`);

            src.push(`${outColor} = vec4(outgoingLight * aoFactor${sao ? ` * ${sao.getAmbient(gl_FragCoord)}` : ""}, opacity);`);

            getGammaOutputExpression && src.push(`${outColor} = ${getGammaOutputExpression(outColor)};`);
        }
    };
};

export const PickDepthProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled) {
    const far  = programVariables.createUniform("float", "far",  (set, state) => set(state.legacyFrameCtx.viewParams.far));
    const near = programVariables.createUniform("float", "near", (set, state) => set(state.legacyFrameCtx.viewParams.near));
    const vViewPosition = programVariables.createVarying("vec3", "vViewPosition", () => `${geometry.attributes.position.view}.xyz`);
    const outPackedDepth = programVariables.createOutput("vec4", "outPackedDepth");
    const packDepth = programVariables.createFragmentDefinition(
        "packDepth",
        (name, src) => {
            src.push(`vec4 ${name}(const in float depth) {`);
            src.push("  const vec4 bitShift = vec4(256.0*256.0*256.0, 256.0*256.0, 256.0, 1.0);");
            src.push("  const vec4 bitMask  = vec4(0.0, 1.0/256.0, 1.0/256.0, 1.0/256.0);");
            src.push("  vec4 res = fract(depth * bitShift);");
            src.push("  res -= res.xxyz * bitMask;");
            src.push("  return res;");
            src.push("}");
        });

    return {
        programName: "PickDepth",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 3,  // PICK
        incPointSizeBy10: true,
        appendFragmentOutputs: (src) => {
            src.push(`float zNormalizedDepth = abs((${near} + ${vViewPosition}.z) / (${far} - ${near}));`);
            // isn't zNormalizedDepth the same as gl_FragDepth or gl_FragCoord.z?
            src.push(`${outPackedDepth} = ${packDepth}(zNormalizedDepth);`); // Must be linear depth
            // try: src.push("    outPackedDepth = vec4(zNormalizedDepth, fract(zNormalizedDepth * vec3(256.0, 256.0*256.0, 256.0*256.0*256.0)));");
        }
    };
};

export const PickMeshProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled) {
    const vPickColor = programVariables.createVarying("vec4", "vPickColor", () => `${geometry.attributes.pickColor} / 255.0`);
    const outPickColor = programVariables.createOutput("vec4", "outPickColor");
    return {
        programName: "PickMesh",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 3,  // PICK
        incPointSizeBy10: true,
        dontCullOnAlphaZero: true, // should be false?
        appendFragmentOutputs: (src) => src.push(`${outPickColor} = ${vPickColor};`)
    };
};

import {math} from "../../../math/math.js";

export const PickNormalsProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled, isFlat) {
    const vWorldPosition = programVariables.createVarying("vec3", "vWorldPosition", () => `${geometry.attributes.position.world}.xyz`);
    const vWorldNormal = programVariables.createVarying("vec3", "vWorldNormal", () => geometry.attributes.normal.world);
    const outNormal = programVariables.createOutput("highp ivec4", "outNormal");
    return {
        programName: isFlat ? "PickNormalsFlat" : "PickNormals",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 3,  // PICK
        appendFragmentOutputs: (src) => {
            const worldNormal = (isFlat
                                 ? `normalize(cross(dFdx(${vWorldPosition}), dFdy(${vWorldPosition})))`
                                 : vWorldNormal);
            src.push(`${outNormal} = ivec4(${worldNormal} * float(${math.MAX_INT}), 1.0);`);
        }
    };
};

export const ShadowProgram = function(programVariables, logarithmicDepthBufferEnabled) {
    // VBOBatchingPointsShadowRenderer has been implemented by 14e973df6268369b00baef60e468939e062ac320,
    // but never used (and probably not maintained), as opposed to VBOInstancingPointsShadowRenderer in the same commit
    const outColor = programVariables.createOutput("vec4", "outColor");
    const encodeFloat = programVariables.createFragmentDefinition(
        "encodeFloat",
        (name, src) => {
            src.push(`vec4 ${name}(const in float v) {`);
            src.push("  const vec4 bitShift = vec4(256 * 256 * 256, 256 * 256, 256, 1.0);");
            src.push("  const vec4 bitMask = vec4(0, 1.0 / 256.0, 1.0 / 256.0, 1.0 / 256.0);");
            src.push("  vec4 comp = fract(v * bitShift);");
            src.push("  comp -= comp.xxyz * bitMask;");
            src.push("  return comp;");
            src.push("}");
        });
    return {
        programName: "Shadow",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 0,
        isShadowProgram: true,
        appendFragmentOutputs: (src, getGammaOutputExpression, gl_FragCoord) => src.push(`${outColor} = ${encodeFloat}(${gl_FragCoord}.z);`)
    };
};

export const SilhouetteProgram = function(programVariables, geometry, logarithmicDepthBufferEnabled, isPointsOrLines) {
    const silhouetteColor = programVariables.createUniform("vec4", "silhouetteColor", (set, state) => set(state.legacyFrameCtx.programColor));
    const vAlpha = programVariables.createVarying("float", "vAlpha", () => `${geometry.attributes.color}.a`);
    const outColor = programVariables.createOutput("vec4", "outColor");
    return {
        programName: "Silhouette",
        getLogDepth: logarithmicDepthBufferEnabled && (vFragDepth => vFragDepth),
        renderPassFlag: 1,  // SILHOUETTE_HIGHLIGHTED | SILHOUETTE_SELECTED | SILHOUETTE_XRAYED
        appendFragmentOutputs: (src, getGammaOutputExpression, gl_FragCoord, sliceColorOr) => {
            src.push(`${outColor} = ${isPointsOrLines
                                      ? silhouetteColor
                                      : sliceColorOr(`vec4(${silhouetteColor}.rgb, min(${silhouetteColor}.a, ${vAlpha}))`)};`);
        }
    };
};

import {math} from "../../../math/math.js";

export const SnapProgram = function(programVariables, geometry, isSnapInit, isPoints) {
    const layerNumber      = programVariables.createUniform("int",  "layerNumber",      (set, state) => set(state.legacyFrameCtx.snapPickLayerParams.length));
    const coordinateScaler = programVariables.createUniform("vec3", "coordinateScaler", (set, state) => set(state.legacyFrameCtx.snapPickCoordinateScale));

    const vWorldPosition = programVariables.createVarying("vec3", "vWorldPosition", () => `${geometry.attributes.position.world}.xyz`);
    const vPickColor = programVariables.createVarying("vec4", "vPickColor", () => geometry.attributes.pickColor); // Using `flat` causes an instability - see XEOK-385 and XEOK-401

    const outCoords    = programVariables.createOutput("highp ivec4", "outCoords", 0);
    const outNormal    = programVariables.createOutput("highp ivec4", "outNormal", 1);
    const outPickColor = programVariables.createOutput("lowp uvec4", "outPickColor", 2);

    return {
        programName: isSnapInit ? "SnapInit" : "Snap",
        // Improves occlusion accuracy at distance
        getLogDepth: true && (vFragDepth => (isSnapInit ? `${vFragDepth} + length(vec2(dFdx(${vFragDepth}), dFdy(${vFragDepth})))` : vFragDepth)),
        renderPassFlag: 3,  // PICK
        vertexCullX: (!isSnapInit) && "2.0",
        dontCullOnAlphaZero: !isSnapInit,
        appendFragmentOutputs: (src) => {
            src.push(`${outCoords} = ivec4(${vWorldPosition} * ${coordinateScaler}.xyz, ${isSnapInit ? "-" : ""}${layerNumber});`);
            if (isSnapInit) {
                src.push(`${outNormal} = ${isPoints ? "ivec4(1.0)" : `ivec4(normalize(cross(dFdx(${vWorldPosition}), dFdy(${vWorldPosition}))) * float(${math.MAX_INT}), 1.0)`};`);
                src.push(`${outPickColor} = uvec4(${vPickColor});`);
            }
        }
    };
};

