                    this.pixels[lenPixels++] = marker.canvasPos[1];
                } else {
                    marker._setVisible(true);
                }
            }
        }
    }

    destroy() {
        this.markers = {};
        this.markerList.length = 0;
        if (this.positionsBuf) {
            this.positionsBuf.destroy();
        }
        if (this.indicesBuf) {
            this.indicesBuf.destroy();
        }
    }
